"""API keys as key pairs (ARCHITECTURE.md section 11): the SDK holds the
private half and signs each request; the server stores only the public half,
so no bearer secret crosses the network.

    Authorization: Runtime-Ed25519 Credential=<32 hex>,Timestamp=<ns>,Nonce=<32 hex>,Signature=<128 hex>
    Runtime-Project: <32 hex>

The signature is Ed25519 over

    "rtr\\x01" | credential (16, LE) | project (16, LE) | timestamp ns (8, LE)
    | nonce (16) | SHA-256(body) (32) | method | "\\n" | path and query | "\\n"
    | Idempotency-Key (empty when none)

so it is good for one request, on one project, within 60 seconds of the
server's clock. A signed write must carry an Idempotency-Key: a copy replayed
within the minute is then answered from the first one's commit, not run
again. The front's side is engines/front/crates/front/src/signed.rs;
every SDK signs the same test vector to the same header.

Signing uses the ``cryptography`` package when it is installed
(``pip install 'withruntime[keypair]'``), one OpenSSL call; without it, a
pure-Python Ed25519 (RFC 8032) that gives the same signatures, slower."""
from __future__ import annotations

import functools
import hashlib
import os
import re
import struct
import time
from typing import Any, Optional, Union

SIGNED_SCHEME = "Runtime-Ed25519"
SIGNING_KEY_PREFIX = "rtsk_"

_DOMAIN = b"rtr\x01"
_ID = re.compile(r"[0-9a-f]{32}")
_SEED = re.compile(r"[0-9a-f]{64}")

__all__ = ["SIGNED_SCHEME", "SIGNING_KEY_PREFIX", "SigningKey", "generate_key_pair", "signing_key_secret",
           "parse_signing_key", "public_key_of"]


# ── Ed25519 without dependencies (RFC 8032, section 5.1) ──────────────────────
_P = 2**255 - 19
_L = 2**252 + 27742317777372353535851937790883648493
_D = -121665 * pow(121666, _P - 2, _P) % _P
_I = pow(2, (_P - 1) // 4, _P)


def _add(a: tuple[int, int, int, int], b: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
    x1, y1, z1, t1 = a
    x2, y2, z2, t2 = b
    a_ = (y1 - x1) * (y2 - x2) % _P
    b_ = (y1 + x1) * (y2 + x2) % _P
    c = 2 * t1 * t2 * _D % _P
    d = 2 * z1 * z2 % _P
    e, f, g, h = b_ - a_, d - c, d + c, b_ + a_
    return e * f % _P, g * h % _P, f * g % _P, e * h % _P


def _mul(s: int, p: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
    q = (0, 1, 1, 0)
    while s:
        if s & 1:
            q = _add(q, p)
        p = _add(p, p)
        s >>= 1
    return q


def _recover_x(y: int, sign: int) -> int:
    x2 = (y * y - 1) * pow(_D * y * y + 1, _P - 2, _P)
    x = pow(x2, (_P + 3) // 8, _P)
    if (x * x - x2) % _P:
        x = x * _I % _P
    return _P - x if (x & 1) != sign else x


_GY = 4 * pow(5, _P - 2, _P) % _P
_GX = _recover_x(_GY, 0)
_G = (_GX, _GY, 1, _GX * _GY % _P)


def _encode(p: tuple[int, int, int, int]) -> bytes:
    zi = pow(p[2], _P - 2, _P)
    x, y = p[0] * zi % _P, p[1] * zi % _P
    return int.to_bytes(y | ((x & 1) << 255), 32, "little")


def _expand(seed: bytes) -> tuple[int, bytes]:
    h = hashlib.sha512(seed).digest()
    a = int.from_bytes(h[:32], "little")
    a &= (1 << 254) - 8
    a |= 1 << 254
    return a, h[32:]


def _pure_public(seed: bytes) -> bytes:
    return _encode(_mul(_expand(seed)[0], _G))


def _pure_sign(seed: bytes, public: bytes, message: bytes) -> bytes:
    a, prefix = _expand(seed)
    r = int.from_bytes(hashlib.sha512(prefix + message).digest(), "little") % _L
    big_r = _encode(_mul(r, _G))
    k = int.from_bytes(hashlib.sha512(big_r + public + message).digest(), "little") % _L
    return big_r + int.to_bytes((r + k * a) % _L, 32, "little")


try:  # One OpenSSL call when the cryptography package is installed.
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey as _OpenSSLKey
except ImportError:  # pragma: no cover - depends on the environment
    _OpenSSLKey = None  # type: ignore[assignment,misc]


def _id_bytes(value: str) -> bytes:
    """A 128-bit ID's 16 bytes, little-endian, as the server reads it."""
    return bytes.fromhex(value)[::-1]


class SigningKey:
    """A key pair as an API key: ``credential``, the ID its public half was
    registered as (32 hex characters), and ``private_key``, its 32-byte
    Ed25519 private key (seed) as 64 hex characters."""

    def __init__(self, credential: str, private_key: str) -> None:
        if not _ID.fullmatch(credential) or not _SEED.fullmatch(private_key):
            raise ValueError("A signing key is a 32-character credential ID and a 64-character private key, "
                             "in lowercase hex.")
        self.credential, self.private_key = credential, private_key
        self._credential = _id_bytes(credential)
        seed = bytes.fromhex(private_key)
        self._seed = seed
        self._openssl: Any = _OpenSSLKey.from_private_bytes(seed) if _OpenSSLKey is not None else None
        self._public: Optional[bytes] = None

    def __repr__(self) -> str:  # Never the private key: a repr reaches logs.
        return f"SigningKey(credential={self.credential!r})"

    @property
    def public_key(self) -> str:
        """The public key, as 64 hex characters: what is registered."""
        if self._public is None:
            if self._openssl is not None:
                from cryptography.hazmat.primitives import serialization
                self._public = self._openssl.public_key().public_bytes(
                    serialization.Encoding.Raw, serialization.PublicFormat.Raw)
            else:
                self._public = _pure_public(self._seed)
        return self._public.hex()

    def _sign(self, message: bytes) -> bytes:
        if self._openssl is not None:
            return self._openssl.sign(message)
        return _pure_sign(self._seed, bytes.fromhex(self.public_key), message)

    def sign_request(self, project: str, method: str, target: str, body: Union[bytes, str, None] = None, *,
                     idempotency_key: Optional[str] = None, timestamp_ns: Optional[int] = None,
                     nonce: Optional[bytes] = None) -> dict[str, str]:
        """The headers that sign one request: ``Authorization`` and
        ``Runtime-Project``. ``target`` is the path and query exactly as sent;
        ``body`` the bytes as sent; ``idempotency_key`` the Idempotency-Key
        header sent, which a write must have. Sign each attempt anew: the
        server takes a nonce once."""
        if not _ID.fullmatch(project):
            raise ValueError("The project is its 32-character ID, in lowercase hex.")
        nonce = os.urandom(16) if nonce is None else nonce
        if len(nonce) != 16:
            raise ValueError("A nonce is 16 bytes.")
        at = time.time_ns() if timestamp_ns is None else timestamp_ns
        data = body.encode() if isinstance(body, str) else (body or b"")
        message = b"".join((_DOMAIN, self._credential, _id_bytes(project), struct.pack("<Q", at), nonce,
                            hashlib.sha256(data).digest(), method.encode(), b"\n", target.encode(), b"\n",
                            (idempotency_key or "").encode()))
        signature = self._sign(message)
        return {
            "Authorization": f"{SIGNED_SCHEME} Credential={self.credential},Timestamp={at},"
                             f"Nonce={nonce.hex()},Signature={signature.hex()}",
            "Runtime-Project": project,
        }


def generate_key_pair() -> tuple[str, str]:
    """A new key pair, made on this machine: ``(private_key, public_key)``, each
    64 hex characters. Register the public key as an API key; keep the private
    key secret. The server never sees it."""
    seed = os.urandom(32).hex()
    return seed, public_key_of(seed)


def public_key_of(private_key: str) -> str:
    """The public key (64 hex characters) of a private key."""
    return SigningKey("0" * 32, private_key).public_key


def signing_key_secret(credential: str, private_key: str) -> str:
    """A key pair's secret, ``rtsk_<credential>_<private_key>``: what
    RUNTIME_API_KEY or ``api_key`` holds to sign requests instead of sending a
    bearer key."""
    SigningKey(credential, private_key)
    return f"{SIGNING_KEY_PREFIX}{credential}_{private_key}"


def parse_signing_key(secret: str) -> Optional[SigningKey]:
    """The key pair in an ``rtsk_`` secret, or None for any other key."""
    if not secret.startswith(SIGNING_KEY_PREFIX):
        return None
    parts = secret[len(SIGNING_KEY_PREFIX):].split("_")
    if len(parts) != 2 or not _ID.fullmatch(parts[0]) or not _SEED.fullmatch(parts[1]):
        return None
    return SigningKey(parts[0], parts[1])


# An rtsk_ secret is a private key: every call that authorizes with the API
# key goes through ``authorize`` (signs) or ``bearer_key`` (refuses it), so
# it is never sent, whatever the call.


def is_signing_key(key: str) -> bool:
    """Whether ``key`` is a key pair's secret (``rtsk_``): a private key,
    which signs requests and is never sent."""
    return key.startswith(SIGNING_KEY_PREFIX)


def _never_sent(message: str, hint: str) -> Exception:
    # A key refused before anything is sent: a programming error, not the API's.
    return ValueError(f"{message} {hint}")


def bearer_key(key: str, what: str) -> str:
    """``key``, for a call that can only send a bearer key (another
    platform's SDK pointed at Runtime). A key pair's secret is never sent:
    raises for one, before anything leaves this machine."""
    if not is_signing_key(key):
        return key
    raise _never_sent(f"{what} sends the API key as a bearer token, and this key is a key pair's private key "
                      "(rtsk_), which is never sent. Nothing was sent.",
                      "Use a bearer API key (rtkey_) here; the SDK's own calls sign with the rtsk_ key.")


def signing_key_for(key: str, project: Optional[str]) -> Optional[SigningKey]:
    """The key pair in ``key``, or None for a bearer key. Raises for a
    malformed ``rtsk_`` secret, or one with no ``project`` to sign for:
    callers check before sending anything."""
    if not is_signing_key(key):
        return None
    signing = _parsed(key)
    if signing is None:
        raise _never_sent("The API key starts with rtsk_ but is not a key pair's secret (rtsk_<32 hex>_<64 hex>). "
                          "Nothing was sent.", "Use the whole secret, as signing_key_secret wrote it.")
    if not project or not _ID.fullmatch(project):
        raise _never_sent("A signing key (rtsk_) signs each request for one project, and none was given. "
                          "Nothing was sent.", "Set RUNTIME_PROJECT to the project's 32-character ID, or pass project=.")
    return signing


@functools.lru_cache(maxsize=16)
def _parsed(secret: str) -> Optional[SigningKey]:
    # Parsed once per secret: each request signs with the same loaded key.
    return parse_signing_key(secret)


def authorize(key: str, project: Optional[str], method: str, target: str, body: Union[bytes, str, None] = None, *,
              idempotency_key: Optional[str] = None) -> dict[str, str]:
    """The headers that authorize one attempt with ``key``: a key pair's
    signature (``SigningKey.sign_request``), else ``Authorization: Bearer``.
    Raises, sending nothing, for a malformed ``rtsk_`` secret or one with no
    project. Call it for each attempt: the server takes a nonce once."""
    signing = signing_key_for(key, project)
    if signing is None:
        # The project goes with every call, a bearer key's too: a key that
        # reaches the whole org would otherwise list, change and delete in
        # every project.
        return {"Authorization": f"Bearer {key}", **({"Runtime-Project": project} if project else {})}
    return signing.sign_request(project or "", method, target, body, idempotency_key=idempotency_key)
